// Renders every table, chart and the in-browser predictor from window.SITE_DATA
// (generated by src/export_site.py). No numbers are hard-coded here.
(function () {
  "use strict";
  const D = window.SITE_DATA;
  if (!D) { document.getElementById("heroAnswer").textContent = "data.js failed to load."; return; }

  const meta = D.meta, dq = meta.data_quality;
  const BEST = meta.best_model_name;
  const $ = (id) => document.getElementById(id);
  const f2 = (v) => Number(v).toFixed(2);
  const f3 = (v) => Number(v).toFixed(3);
  const pct = (v) => Math.round(v * 100) + "%";
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const model = (name) => D.models.find((m) => m.Model === name);
  const NICE = {
    Age: "Age", Avg_Daily_Usage_Hours: "Social media h/day", Daily_Unlocks: "Phone unlocks/day",
    Study_Hours: "Study h/day", Physical_Activity_Hours: "Exercise h/day", Sleep_Hours_Per_Night: "Sleep h/night",
    Mental_Health_Score: "Mental_Health_Score (target)", Gender: "Gender", Country: "Country",
    Academic_Level: "Academic level", Most_Used_Platform: "Platform", Purpose_Of_Use: "Purpose",
  };

  // ---------- generic table + svg helpers ----------
  function table(el, headers, rows, rowClass) {
    const th = headers.map((h) => `<th class="${h.n ? "n" : ""}">${h.t}</th>`).join("");
    const tr = rows.map((r, i) => `<tr class="${rowClass ? rowClass(i) : ""}">` +
      r.map((c, j) => `<td class="${headers[j].n ? "n" : ""}">${c}</td>`).join("") + "</tr>").join("");
    el.innerHTML = `<thead><tr>${th}</tr></thead><tbody>${tr}</tbody>`;
  }
  const svg = (w, h, body) => `<svg viewBox="0 0 ${w} ${h}" role="img">${body}</svg>`;

  function hbar(el, items, opt = {}) {
    const W = 460, rowH = 26, left = opt.left || 190, right = 56, H = items.length * rowH + 22;
    const max = opt.max || Math.max(...items.map((d) => d.hi ?? d.value)) * 1.05;
    const x = (v) => left + (v / max) * (W - left - right);
    let b = `<line class="axis" x1="${left}" x2="${left}" y1="0" y2="${H - 18}"/>`;
    items.forEach((d, i) => {
      const y = i * rowH + 4;
      b += `<text x="${left - 6}" y="${y + 14}" text-anchor="end" class="${d.cls === "sel" ? "lbl" : ""}">${esc(d.label)}</text>`;
      b += `<rect class="bar ${d.cls || ""}" x="${left}" y="${y + 2}" width="${Math.max(1, x(d.value) - left)}" height="${rowH - 10}" rx="2"/>`;
      if (d.lo != null) b += `<line class="ci" x1="${x(d.lo)}" x2="${x(d.hi)}" y1="${y + 10}" y2="${y + 10}"/>` +
        `<line class="ci" x1="${x(d.lo)}" x2="${x(d.lo)}" y1="${y + 6}" y2="${y + 14}"/><line class="ci" x1="${x(d.hi)}" x2="${x(d.hi)}" y1="${y + 6}" y2="${y + 14}"/>`;
      b += `<text x="${x(d.hi ?? d.value) + 5}" y="${y + 14}" class="lbl">${(opt.fmt || f3)(d.value)}</text>`;
    });
    b += `<text x="${left}" y="${H - 4}">0</text><text x="${W - right}" y="${H - 4}" text-anchor="end">${opt.axis || ""}</text>`;
    el.innerHTML = svg(W, H, b);
  }

  function vbar(el, labels, values, opt = {}) {
    const W = 460, H = 220, L = 34, B = 30, T = 10;
    const max = Math.max(...values) * 1.1, bw = (W - L - 10) / values.length;
    let b = `<line class="axis" x1="${L}" x2="${W - 5}" y1="${H - B}" y2="${H - B}"/>`;
    values.forEach((v, i) => {
      const h = (v / max) * (H - B - T), xx = L + i * bw;
      b += `<rect class="bar ${opt.cls ? opt.cls(i) : ""}" x="${xx + 2}" y="${H - B - h}" width="${bw - 4}" height="${h}" rx="2"><title>${labels[i]}: ${v}</title></rect>`;
      if (opt.valueLabels) b += `<text x="${xx + bw / 2}" y="${H - B - h - 4}" text-anchor="middle" class="lbl">${opt.valueLabels(v)}</text>`;
      if (!opt.every || i % opt.every === 0) b += `<text x="${xx + bw / 2}" y="${H - B + 14}" text-anchor="middle">${labels[i]}</text>`;
    });
    if (opt.xTitle) b += `<text x="${(W + L) / 2}" y="${H - 2}" text-anchor="middle">${opt.xTitle}</text>`;
    el.innerHTML = svg(W, H, b);
  }

  // ---------- fill simple keys ----------
  document.querySelectorAll("[data-k]").forEach((el) => {
    const k = el.dataset.k;
    const v = dq[k] ?? meta[k];
    el.textContent = typeof v === "number" ? v.toLocaleString() : v;
  });
  document.querySelectorAll(".best-name").forEach((el) => (el.textContent = BEST));

  // ---------- hero ----------
  const best = model(BEST), dummy = model("Baseline: Mean (Dummy)"), lin = model("Linear Regression");
  const rf = model("Random Forest");
  const cBest = D.country.find((c) => c.Model === BEST);
  const cBestUnseen = D.country.reduce((a, b) => (b.Country_GroupKFold_RMSE < a.Country_GroupKFold_RMSE ? b : a));
  $("heroAnswer").innerHTML =
    `Within this dataset, <strong>yes, for students from countries the model has seen</strong>. The selected ${BEST} model misses by ` +
    `<strong>${f2(best.Test_MAE)} points</strong> on a 10-point scale (typical error) on ${meta.test_size.toLocaleString()} held-out students, ` +
    `against ${f2(dummy.Test_MAE)} for predicting the average. <strong>For unseen countries, accuracy drops sharply</strong>, and the ` +
    `results should not be read as causal or clinical.`;
  $("heroStats").innerHTML = [
    [f3(best.Test_RMSE), `Test RMSE, ${BEST} (95% CI ${f3(best.Test_RMSE_CI_Low)}–${f3(best.Test_RMSE_CI_High)})`],
    [f3(lin.Test_RMSE), "Test RMSE, linear regression baseline"],
    [f3(dummy.Test_RMSE), "Test RMSE, predict-the-mean baseline"],
    [f3(cBest.Country_GroupKFold_RMSE), `CV RMSE of ${BEST} on unseen countries`],
  ].map(([v, t]) => `<div class="stat"><b>${v}</b><span>${t}</span></div>`).join("");

  // ---------- data section ----------
  const DESC = {
    Age: "Age in years", Avg_Daily_Usage_Hours: "Self-reported daily social-media time",
    Daily_Unlocks: "Phone unlocks per day", Study_Hours: "Study time per day",
    Physical_Activity_Hours: "Exercise per day (10 negatives clipped to 0)", Sleep_Hours_Per_Night: "Average nightly sleep",
    Mental_Health_Score: "Self-rated wellbeing, 1–10 (higher = better)",
  };
  table($("varTable"),
    [{ t: "Variable" }, { t: "Meaning" }, { t: "Min", n: 1 }, { t: "Mean", n: 1 }, { t: "Max", n: 1 }, { t: "r with target", n: 1 }],
    D.eda.numeric_summary.map((s) => [`<code>${s.feature}</code>`, DESC[s.feature] || "", s.min, s.mean, s.max,
      s.feature === "Mental_Health_Score" ? "–" : f2(s.r_with_target)]));

  const otherShare = pct(dq.share_country_other);
  $("qualityList").innerHTML = [
    `<b>${dq.raw_rows.toLocaleString()}</b> raw rows, <b>${dq.missing_values}</b> missing values, and <b>${dq.exact_duplicates_removed}</b> exact duplicates removed, leaving ${dq.rows_after_cleaning.toLocaleString()} rows.`,
    `<b>${dq.negative_activity_clipped}</b> negative exercise values clipped to 0.`,
    `Time budget check: the largest sum of social media + study + sleep + exercise is <b>${dq.max_daily_hours_sum} h</b>, so no row is impossible (more than 24 h).`,
    `Only <b>${dq.target_unique_values}</b> distinct target values (one decimal place), so the score is coarse and some error comes from rounding alone.`,
    `<b>Country</b> has ${dq.n_countries} values, but <b>"Other" covers ${otherShare}</b> of rows, a mixed bucket rather than one country.`,
    `<b>Platform almost determines purpose</b>: the most common purpose per platform accounts for ${pct(D.eda.platform_purpose_determinism)} of rows (e.g. LinkedIn is always "Education"). The two columns overlap heavily.`,
    `<b>Usage hours and unlocks are highly correlated</b> (r = ${f2(D.eda.usage_unlocks_r)}). Individual linear coefficients for them are therefore unstable, which motivates Ridge.`,
    `Only <b>${dq.test_rows_with_identical_features_in_train}</b> test rows have an exact feature twin in training, so the test score is not driven by copied rows.`,
  ].map((s) => `<li>${s}</li>`).join("");

  const h = D.eda.target_hist;
  vbar($("histChart"), h.edges.slice(0, -1).map((e) => e.toFixed(1)), h.counts,
    { every: 2, xTitle: "Mental_Health_Score (bin start)", cls: (i) => (h.edges[i] < meta.threshold_25th ? "alt" : "") });
  vbar($("stressChart"), D.eda.stress_vs_target.map((s) => s.Stress_Level), D.eda.stress_vs_target.map((s) => s.mean),
    { valueLabels: (v) => v.toFixed(2), xTitle: "Stress_Level → mean Mental_Health_Score" });

  // ---------- method table ----------
  const order = D.models.slice().sort((a, b) => (a.Role === "baseline" ? -1 : 0) - (b.Role === "baseline" ? -1 : 0));
  table($("methodTable"), [{ t: "Model" }, { t: "Role" }, { t: "Why it is here" }, { t: "Chosen hyper-parameters" }],
    order.map((m) => [m.Model, m.Role === "selected" ? "candidate (selected)" : m.Role, m.Why,
      m.Best_Params === "default" ? "–" : `<code>${esc(m.Best_Params)}</code>`]));

  // ---------- results ----------
  const rfGap = rf.Delta_CI_Low <= 0;
  $("resultsLead").innerHTML =
    `The selected model is <strong>${BEST}</strong> (<code>${esc(JSON.stringify(meta.best_params))}</code>), chosen because it has the lowest CV RMSE ` +
    `(${f3(best.CV_RMSE)} ± ${f3(best.CV_RMSE_Std)}). Its test RMSE (${f3(best.Test_RMSE)}) is close to its CV RMSE, so tuning did not overfit. ` +
    `It beats linear regression by ${f3(lin.Delta_RMSE_vs_Selected)} RMSE (95% CI ${f3(lin.Delta_CI_Low)} to ${f3(lin.Delta_CI_High)}), ` +
    `which points to non-linear or local structure that an additive model misses. ` +
    (rfGap ? `Its lead over <strong>Random Forest is not clear</strong>: the gap is ${f3(rf.Delta_RMSE_vs_Selected)} with a CI from ${f3(rf.Delta_CI_Low)} to ${f3(rf.Delta_CI_High)}, which includes 0. The two are statistically tied on this test set.`
      : `It also beats Random Forest (gap ${f3(rf.Delta_RMSE_vs_Selected)}, CI ${f3(rf.Delta_CI_Low)}–${f3(rf.Delta_CI_High)}).`);

  table($("modelTable"),
    [{ t: "Model" }, { t: "CV RMSE (± sd)", n: 1 }, { t: "Test RMSE [95% CI]", n: 1 }, { t: "Test MAE", n: 1 }, { t: "Test R²", n: 1 }, { t: "ΔRMSE vs selected [95% CI]", n: 1 }],
    D.models.map((m) => [
      m.Model + (m.Role === "selected" ? '<span class="tag">selected</span>' : m.Role === "baseline" ? '<span class="tag">baseline</span>' : ""),
      `${f3(m.CV_RMSE)} ± ${f3(m.CV_RMSE_Std)}`,
      `${f3(m.Test_RMSE)} [${f3(m.Test_RMSE_CI_Low)}, ${f3(m.Test_RMSE_CI_High)}]`,
      f3(m.Test_MAE), f3(m.Test_R2),
      m.Delta_RMSE_vs_Selected == null ? "–" : `+${f3(m.Delta_RMSE_vs_Selected)} [${f3(m.Delta_CI_Low)}, ${f3(m.Delta_CI_High)}]`,
    ]), (i) => (D.models[i].Role === "selected" ? "sel" : D.models[i].Role === "baseline" ? "base" : ""));

  hbar($("rmseChart"), D.models.map((m) => ({
    label: m.Model.replace("Baseline: ", ""), value: m.Test_RMSE, lo: m.Test_RMSE_CI_Low, hi: m.Test_RMSE_CI_High,
    cls: m.Role === "selected" ? "sel" : m.Role === "baseline" ? "dim" : "",
  })), { axis: "RMSE (score points)" });

  (function scatter() {
    const W = 460, H = 320, L = 36, B = 30, lo = 3, hi = 10;
    const sx = (v) => L + ((v - lo) / (hi - lo)) * (W - L - 10), sy = (v) => H - B - ((v - lo) / (hi - lo)) * (H - B - 10);
    let b = `<line class="axis" x1="${L}" x2="${W - 10}" y1="${H - B}" y2="${H - B}"/><line class="axis" x1="${L}" x2="${L}" y1="10" y2="${H - B}"/>`;
    b += `<line class="ref" x1="${sx(lo)}" y1="${sy(lo)}" x2="${sx(hi)}" y2="${sy(hi)}"/>`;
    D.scatter.forEach(([a, p]) => (b += `<circle class="dot" cx="${sx(a).toFixed(1)}" cy="${sy(p).toFixed(1)}" r="2.4"/>`));
    for (let t = 4; t <= 10; t += 2) b += `<text x="${sx(t)}" y="${H - B + 14}" text-anchor="middle">${t}</text><text x="${L - 6}" y="${sy(t) + 4}" text-anchor="end">${t}</text>`;
    b += `<text x="${(W + L) / 2}" y="${H - 2}" text-anchor="middle">actual</text><text x="12" y="${H / 2}" transform="rotate(-90 12 ${H / 2})" text-anchor="middle">predicted</text>`;
    $("scatterChart").innerHTML = svg(W, H, b);
  })();

  // country
  table($("countryTable"), [{ t: "Model" }, { t: "Random 5-fold", n: 1 }, { t: "Unseen countries", n: 1 }, { t: "R² unseen", n: 1 }],
    D.country.map((c) => [c.Model, f3(c.Random_KFold_RMSE), `${f3(c.Country_GroupKFold_RMSE)} ± ${f3(c.Country_GroupKFold_RMSE_Std)}`, f3(c.Country_GroupKFold_R2)]),
    (i) => (D.country[i].Model === BEST ? "sel" : ""));
  const linC = D.country.find((c) => c.Model === "Linear Regression");
  $("countryText").innerHTML =
    `<p>When whole countries are held out, the RMSE of ${BEST} rises from ${f3(cBest.Random_KFold_RMSE)} to <strong>${f3(cBest.Country_GroupKFold_RMSE)}</strong>. ` +
    `That is worse than linear regression (${f3(linC.Country_GroupKFold_RMSE)}). The best model on unseen countries is <strong>${cBestUnseen.Model}</strong> (${f3(cBestUnseen.Country_GroupKFold_RMSE)}).</p>` +
    `<p>So the answer to the second half of the question is <strong>"only partly"</strong>. Much of the in-distribution accuracy comes from learning country-specific patterns. ` +
    `For a student from a new country, use ${cBestUnseen.Model} and expect errors about twice as large.</p>`;

  // feature groups
  table($("groupTable"), [{ t: "Inputs used" }, { t: "KNN", n: 1 }, { t: "Ridge", n: 1 }],
    D.feature_groups.map((g) => [g.Feature_Group, f3(g.KNN_CV_RMSE), f3(g.Ridge_CV_RMSE)]));
  hbar($("permChart"), D.permutation.map((p) => ({ label: NICE[p.Feature] || p.Feature, value: Math.max(0, p.RMSE_Increase) })),
    { left: 150, axis: "RMSE increase" });
  const fg = (k) => D.feature_groups.find((g) => g.Feature_Group.startsWith(k));
  const all = fg("All"), noC = fg("Everything except"), demo = fg("Demographics"), life = fg("Lifestyle"), dig = fg("Digital");
  $("groupText").innerHTML =
    `<p>Digital use alone (${f3(dig.KNN_CV_RMSE)}) and lifestyle alone (${f3(life.Ridge_CV_RMSE)} with Ridge) each recover much of the signal. Demographics alone are close to the mean baseline (${f3(demo.Ridge_CV_RMSE)}).</p>` +
    `<p>Removing <b>country</b> raises KNN's error from ${f3(all.KNN_CV_RMSE)} to ${f3(noC.KNN_CV_RMSE)}, and country is the second-largest permutation importance. ` +
    `This matches the unseen-country result: part of KNN's edge comes from matching students to similar students <em>from the same country</em>. ` +
    `Permutation importance describes what the model relies on, not what causes wellbeing.</p>`;

  // stress ablation
  table($("stressTable"), [{ t: "Model" }, { t: "Condition" }, { t: "CV RMSE", n: 1 }, { t: "CV R²", n: 1 }],
    D.stress_ablation.map((s) => [s.Model, s.Condition, f3(s.CV_RMSE), f3(s.CV_R2)]));
  const sa = (m, w) => D.stress_ablation.find((s) => s.Model === m && s.Condition.startsWith(w));
  $("stressText").innerHTML =
    `<p>Adding <code>Stress_Level</code> barely changes CV error (${BEST}: ${f3(sa(BEST, "Without").CV_RMSE)} → ${f3(sa(BEST, "With").CV_RMSE)}; ` +
    `Ridge: ${f3(sa("Ridge Regression", "Without").CV_RMSE)} → ${f3(sa("Ridge Regression", "With").CV_RMSE)}), because the habit variables already capture what it would add.</p>` +
    `<p>It is excluded for <strong>validity, not accuracy</strong>: it is a concurrent outcome-like measure that would not exist when making a real prediction. ` +
    `Both arms use the same model and the same folds, so the comparison is fair.</p>`;

  // ---------- errors ----------
  function renderSubgroups(g) {
    const rows = D.subgroups.filter((s) => s.group === g);
    table($("subgroupTable"), [{ t: "Group" }, { t: "n", n: 1 }, { t: "RMSE", n: 1 }, { t: "MAE", n: 1 }, { t: "Bias (pred − actual)", n: 1 }],
      rows.map((r) => [esc(r.value), r.n, f3(r.RMSE), f3(r.MAE), `<span class="${r.bias > 0 ? "pos" : "neg"}">${r.bias > 0 ? "+" : ""}${f3(r.bias)}</span>`]));
    const worstR = rows.reduce((a, b) => (b.RMSE > a.RMSE ? b : a)), bestR = rows.reduce((a, b) => (b.RMSE < a.RMSE ? b : a));
    let txt = `<p>Highest error: <b>${esc(worstR.value)}</b> (RMSE ${f3(worstR.RMSE)}, n = ${worstR.n}). Lowest: <b>${esc(bestR.value)}</b> (${f3(bestR.RMSE)}).</p>`;
    if (g === "band") {
      const low = rows[0], top = rows[rows.length - 1];
      txt += `<p><b>Shrinkage toward the middle:</b> the lowest scorers are over-predicted (${low.bias > 0 ? "+" : ""}${f3(low.bias)}) and the highest under-predicted (${f3(top.bias)}). ` +
        `Averaging neighbours pulls extremes in, so the model is least reliable for the students who would matter most for screening.</p>`;
    } else if (g === "country_group") {
      txt += `<p>The mixed <b>"Other"</b> bucket is among the hardest: it groups many countries, so "same country" neighbours are less informative.</p>`;
    } else if (g === "Academic_Level") {
      txt += `<p>Smaller groups (e.g. High School, n = ${(rows.find((r) => r.value === "High School") || {}).n}) have higher error, and their estimates are also noisier because n is small.</p>`;
    } else {
      txt += `<p>The gap between groups is small compared with the overall test-RMSE CI (${f3(best.Test_RMSE_CI_Low)}–${f3(best.Test_RMSE_CI_High)}).</p>`;
    }
    $("subgroupText").innerHTML = txt;
  }
  $("groupSelect").addEventListener("change", (e) => renderSubgroups(e.target.value));
  renderSubgroups("band");

  table($("worstTable"),
    [{ t: "Actual", n: 1 }, { t: "Pred.", n: 1 }, { t: "Miss", n: 1 }, { t: "Social media", n: 1 }, { t: "Sleep", n: 1 }, { t: "Study", n: 1 }, { t: "Platform" }, { t: "Country" }, { t: "Level" }],
    D.worst.map((w) => [f2(w.actual), f2(w.pred), `<b>${w.residual > 0 ? "+" : ""}${f2(w.residual)}</b>`, w.Avg_Daily_Usage_Hours, w.Sleep_Hours_Per_Night, w.Study_Hours, w.Most_Used_Platform, w.Country, w.Academic_Level]));
  const absErr = D.scatter.map(([a, p]) => Math.abs(a - p)).sort((a, b) => a - b);
  const q = (p) => absErr[Math.floor(p * (absErr.length - 1))];
  const within025 = absErr.filter((e) => e <= 0.25).length / absErr.length;
  $("worstText").innerHTML =
    `Most errors are small: ${pct(within025)} of test students are predicted within ±0.25 points, and 90% within ±${f2(q(0.9))}. ` +
    `The largest misses (about ${f2(Math.abs(D.worst[0].residual))} points) are students whose habits look typical of a different score, e.g. average screen time and sleep but a much higher or lower self-rating. ` +
    `Self-reported habits cannot explain everything about how someone rates their own wellbeing.`;

  $("limitsList").innerHTML = [
    "<b>Unknown data provenance.</b> Collection method, sampling and the scoring instrument are undocumented, and the data may be partly simulated. Results may not hold for any real population.",
    "<b>Association, not causation.</b> Sleep or screen time may be consequences of low wellbeing rather than causes. The what-if tool shows model sensitivity only.",
    "<b>Self-report and one time point.</b> Hours and scores are self-estimated. There is no follow-up, so no prediction <em>over time</em>.",
    `<b>Weak transfer across countries.</b> Unseen-country RMSE (${f3(cBest.Country_GroupKFold_RMSE)}) is more than double the in-distribution value, and "Other" lumps ${otherShare} of rows together.`,
    "<b>Extremes are shrunk.</b> The lowest and highest scorers are predicted toward the middle, which limits use as any kind of screening signal.",
    `<b>KNN vs Random Forest is a tie</b> on this test set${rfGap ? " (paired CI includes 0)" : ""}. The choice between them is not strongly supported, and Random Forest transfers better.`,
    "<b>One split.</b> CV standard deviations and bootstrap CIs quantify sampling noise, but a different random split would shift the numbers slightly.",
  ].map((s) => `<li>${s}</li>`).join("");

  // ---------- predictor ----------
  const K = D.knn, R = D.ridge;
  const NUM = K.num_features, CAT = K.cat_features;
  const ranges = Object.fromEntries(D.eda.numeric_summary.map((s) => [s.feature, [s.min, s.max]]));
  CAT.forEach((c) => {
    const sel = $("f_" + c);
    const opts = K.categories[c].slice();
    if (c === "Country") opts.sort((a, b) => (a === "Other") - (b === "Other") || a.localeCompare(b));
    sel.innerHTML = opts.map((v) => `<option>${esc(v)}</option>`).join("");
  });
  const DEFAULTS = { Gender: "Female", Academic_Level: "Undergraduate", Country: "India", Most_Used_Platform: "Instagram", Purpose_Of_Use: "Entertainment" };
  function setDefaults() {
    Object.entries(DEFAULTS).forEach(([k, v]) => ($("f_" + k).value = v));
    const nd = { Age: 21, Avg_Daily_Usage_Hours: 5, Daily_Unlocks: 170, Study_Hours: 3, Physical_Activity_Hours: 1.7, Sleep_Hours_Per_Night: 6.6 };
    Object.entries(nd).forEach(([k, v]) => ($("f_" + k).value = v));
  }

  function readInput() {
    const x = {};
    NUM.forEach((f) => (x[f] = parseFloat($("f_" + f).value)));
    CAT.forEach((f) => (x[f] = $("f_" + f).value));
    return x;
  }

  function knnPredict(x) {
    const z = NUM.map((f, i) => (x[f] - K.mean[i]) / K.scale[i]);
    const ci = CAT.map((f) => K.categories[f].indexOf(x[f]));
    const n = K.train_y.length, best = [];
    for (let r = 0; r < n; r++) {
      const row = K.train_num[r], cr = K.train_cat[r];
      let d2 = 0;
      for (let i = 0; i < z.length; i++) { const t = (row[i] - K.mean[i]) / K.scale[i] - z[i]; d2 += t * t; }
      for (let j = 0; j < ci.length; j++) if (cr[j] !== ci[j]) d2 += 2;
      if (best.length < K.k || d2 < best[best.length - 1].d2) {
        best.push({ r, d2 }); best.sort((a, b) => a.d2 - b.d2); if (best.length > K.k) best.pop();
      }
    }
    best.forEach((b) => (b.d = Math.sqrt(b.d2)));
    let pred;
    if (K.weights === "distance") {
      const zeros = best.filter((b) => b.d === 0);
      if (zeros.length) pred = zeros.reduce((s, b) => s + K.train_y[b.r], 0) / zeros.length;
      else { let ws = 0, s = 0; best.forEach((b) => { const w = 1 / b.d; ws += w; s += w * K.train_y[b.r]; }); pred = s / ws; }
    } else pred = best.reduce((s, b) => s + K.train_y[b.r], 0) / best.length;
    return { pred, neighbours: best };
  }

  function ridgePredict(x) {
    let s = R.intercept;
    NUM.forEach((f, i) => (s += R.num_coef[i] * (x[f] - R.mean[i]) / R.scale[i]));
    CAT.forEach((f) => (s += R.cat_coef[f][x[f]] || 0));
    return s;
  }

  function validate(x) {
    const msgs = [];
    const invalid = NUM.some((f) => !Number.isFinite(x[f]) || x[f] < 0);
    if (invalid) return { ok: false, msgs: ["Please enter a non-negative number in every field."] };
    const total = x.Avg_Daily_Usage_Hours + x.Study_Hours + x.Sleep_Hours_Per_Night + x.Physical_Activity_Hours;
    const box = $("hoursBox");
    box.textContent = `Hours used: ${total.toFixed(1)} / 24`;
    box.classList.toggle("over", total > 24);
    if (total > 24) return { ok: false, msgs: [`Social media + study + sleep + exercise = ${total.toFixed(1)} h, which is more than 24 h in a day. Please reduce the hours.`] };
    NUM.forEach((f) => {
      const [lo, hi] = ranges[f];
      if (x[f] < lo || x[f] > hi) msgs.push(`${NICE[f]} = ${x[f]} is outside the training range (${lo}–${hi}). The prediction is an extrapolation and less reliable.`);
    });
    return { ok: true, msgs };
  }

  const typical = f2(best.Test_MAE), p90 = f2(q(0.9));
  function update(sample) {
    const x = readInput(), v = validate(x);
    const warn = $("warnBox");
    warn.hidden = !v.msgs.length;
    warn.innerHTML = v.msgs.map(esc).join("<br>");
    if (!v.ok) { $("predBig").textContent = "–"; $("predRange").textContent = ""; ["compareTable", "nbTable", "whatifTable"].forEach((id) => ($(id).innerHTML = "")); $("actualBox").hidden = true; return; }

    const k = knnPredict(x), rp = ridgePredict(x);
    $("predBig").textContent = k.pred.toFixed(2);
    $("predRange").textContent = `Typical miss ±${typical}; 90% of test students within ±${p90}`;
    table($("compareTable"), [{ t: "Model" }, { t: "Prediction", n: 1 }], [
      [BEST + " (selected)", f2(k.pred)], ["Ridge (linear)", f2(rp)], ["Mean baseline (training mean)", f2(D.samples[0].pred_dummy)],
    ]);

    table($("nbTable"), [{ t: "Score", n: 1 }, { t: "Dist.", n: 1 }, { t: "Social", n: 1 }, { t: "Sleep", n: 1 }, { t: "Study", n: 1 }, { t: "Country" }, { t: "Platform" }],
      k.neighbours.map((b) => {
        const r = K.train_num[b.r], c = K.train_cat[b.r];
        return [f2(K.train_y[b.r]), f2(b.d), r[NUM.indexOf("Avg_Daily_Usage_Hours")], r[NUM.indexOf("Sleep_Hours_Per_Night")], r[NUM.indexOf("Study_Hours")],
          esc(K.categories.Country[c[CAT.indexOf("Country")]]), esc(K.categories.Most_Used_Platform[c[CAT.indexOf("Most_Used_Platform")]])];
      }));

    const changes = [
      ["Sleep +1 h", { Sleep_Hours_Per_Night: x.Sleep_Hours_Per_Night + 1 }],
      ["Social media −1 h", { Avg_Daily_Usage_Hours: Math.max(0, x.Avg_Daily_Usage_Hours - 1) }],
      ["Unlocks −30", { Daily_Unlocks: Math.max(0, x.Daily_Unlocks - 30) }],
      ["Exercise +0.5 h", { Physical_Activity_Hours: x.Physical_Activity_Hours + 0.5 }],
    ];
    table($("whatifTable"), [{ t: "Change" }, { t: `${BEST}`, n: 1 }, { t: "Ridge", n: 1 }],
      changes.map(([label, ch]) => {
        const x2 = Object.assign({}, x, ch);
        const tot = x2.Avg_Daily_Usage_Hours + x2.Study_Hours + x2.Sleep_Hours_Per_Night + x2.Physical_Activity_Hours;
        if (tot > 24) return [label, "exceeds 24 h", "–"];
        const dk = knnPredict(x2).pred - k.pred, dr = ridgePredict(x2) - rp;
        const s = (d) => `${d >= 0 ? "+" : ""}${f2(d)}`;
        return [label, s(dk), s(dr)];
      }));

    const ab = $("actualBox");
    if (sample) {
      ab.hidden = false;
      ab.innerHTML = `Real held-out test student. <b>Actual score: ${f2(sample.Actual_Mental_Health_Score)}</b>, so this prediction misses by ` +
        `${f2(Math.abs(sample.Actual_Mental_Health_Score - k.pred))}. Python model output: ${f2(sample.pred_best)}; Random Forest ${f2(sample.pred_rf)}; linear ${f2(sample.pred_linear)}.`;
    } else ab.hidden = true;
  }

  let currentSample = null;
  document.querySelectorAll("#predForm input, #predForm select").forEach((el) =>
    el.addEventListener("input", () => { currentSample = null; update(null); }));
  $("sampleBtn").addEventListener("click", () => {
    const s = D.samples[Math.floor(Math.random() * D.samples.length)];
    NUM.concat(CAT).forEach((f) => ($("f_" + f).value = s[f]));
    currentSample = s; update(s);
  });
  $("resetBtn").addEventListener("click", () => { setDefaults(); currentSample = null; update(null); });
  setDefaults(); update(null);

  // expose for parity testing
  window.__knnPredict = knnPredict;

  // ---------- extra charts ----------
  function lineChart(el, series, opt = {}) {
    const W = opt.w || 520, H = opt.h || 260, L = 46, R = 12, T = 26, B = 36;
    const all = series.flatMap((s) => s.pts);
    const xs = all.map((p) => p[0]), ys = all.flatMap((p) => [p[1], p[2] ?? p[1], p[3] ?? p[1]]);
    if (opt.refY != null) ys.push(opt.refY);
    const x0 = Math.min(...xs), x1 = Math.max(...xs);
    let y0 = opt.yMin ?? Math.min(...ys), y1 = opt.yMax ?? Math.max(...ys);
    const py = (y1 - y0) * 0.08; if (opt.yMin == null) y0 -= py; y1 += py;
    const sx = (v) => L + ((v - x0) / (x1 - x0 || 1)) * (W - L - R);
    const sy = (v) => H - B - ((v - y0) / (y1 - y0)) * (H - B - T);
    let b = `<line class="axis" x1="${L}" x2="${W - R}" y1="${H - B}" y2="${H - B}"/><line class="axis" x1="${L}" x2="${L}" y1="${T}" y2="${H - B}"/>`;
    for (let i = 0; i <= 4; i++) {
      const v = y0 + ((y1 - y0) * i) / 4;
      b += `<line class="grid" x1="${L}" x2="${W - R}" y1="${sy(v)}" y2="${sy(v)}"/><text x="${L - 6}" y="${sy(v) + 4}" text-anchor="end">${v.toFixed(opt.yDec ?? 2)}</text>`;
    }
    const xt = opt.xTicks || [...new Set(xs)];
    xt.forEach((v) => (b += `<text x="${sx(v)}" y="${H - B + 14}" text-anchor="middle">${opt.xFmt ? opt.xFmt(v) : v}</text>`));
    if (opt.refY != null) b += `<line class="ref" x1="${L}" x2="${W - R}" y1="${sy(opt.refY)}" y2="${sy(opt.refY)}"/><text x="${W - R}" y="${sy(opt.refY) - 4}" text-anchor="end">${esc(opt.refLabel || "")}</text>`;
    series.forEach((s, si) => {
      if (s.pts[0].length > 2) {
        const up = s.pts.map((p) => `${sx(p[0])},${sy(p[3])}`);
        const dn = s.pts.slice().reverse().map((p) => `${sx(p[0])},${sy(p[2])}`);
        b += `<polygon class="band s${si}" points="${up.concat(dn).join(" ")}"/>`;
      }
      b += `<polyline class="line s${si} ${s.dash ? "dash" : ""}" points="${s.pts.map((p) => `${sx(p[0])},${sy(p[1])}`).join(" ")}"/>`;
      s.pts.forEach((p) => (b += `<circle class="pt s${si}" cx="${sx(p[0])}" cy="${sy(p[1])}" r="3"><title>${esc(s.name)}: ${opt.xFmt ? opt.xFmt(p[0]) : p[0]} → ${p[1].toFixed(3)}</title></circle>`));
    });
    let lx = L + 6;
    series.forEach((s, si) => {
      b += `<rect class="sw s${si}" x="${lx}" y="6" width="10" height="10" rx="2"/><text x="${lx + 14}" y="15" class="lbl">${esc(s.name)}</text>`;
      lx += 26 + s.name.length * 6.2;
    });
    if (opt.xTitle) b += `<text x="${(W + L) / 2}" y="${H - 4}" text-anchor="middle">${esc(opt.xTitle)}</text>`;
    if (opt.yTitle) b += `<text x="11" y="${(H - B + T) / 2}" transform="rotate(-90 11 ${(H - B + T) / 2})" text-anchor="middle">${esc(opt.yTitle)}</text>`;
    el.innerHTML = svg(W, H, b);
  }

  function groupedHbar(el, rows, names, opt = {}) {
    const W = opt.w || 560, left = opt.left || 220, right = 60, gh = names.length * 13 + 12, H = rows.length * gh + 40;
    const max = Math.max(...rows.flatMap((r) => r.values), opt.ref || 0) * 1.08;
    const x = (v) => left + (v / max) * (W - left - right);
    let b = "", lx = left;
    names.forEach((n, i) => {
      b += `<rect class="sw s${i}" x="${lx}" y="4" width="10" height="10" rx="2"/><text x="${lx + 14}" y="13" class="lbl">${esc(n)}</text>`;
      lx += 30 + n.length * 6.2;
    });
    rows.forEach((r, ri) => {
      const y = 24 + ri * gh;
      b += `<text x="${left - 6}" y="${y + gh / 2}" text-anchor="end" class="${r.sel ? "lbl" : ""}">${esc(r.label)}</text>`;
      r.values.forEach((v, i) => {
        const yy = y + i * 13;
        b += `<rect class="sbar s${i}" x="${left}" y="${yy}" width="${Math.max(1, x(v) - left)}" height="11" rx="2"/><text x="${x(v) + 4}" y="${yy + 9}">${f3(v)}</text>`;
      });
    });
    b += `<line class="axis" x1="${left}" x2="${left}" y1="20" y2="${H - 14}"/>`;
    if (opt.ref) b += `<line class="ref" x1="${x(opt.ref)}" x2="${x(opt.ref)}" y1="20" y2="${H - 14}"/><text x="${x(opt.ref)}" y="${H - 2}" text-anchor="middle">${esc(opt.refLabel || "")}</text>`;
    el.innerHTML = svg(W, H, b);
  }

  // Diverging bars around 0. posCls/negCls choose the colour series.
  function divBar(el, items, opt = {}) {
    const W = 460, rowH = 28, left = opt.left || 140, H = items.length * rowH + 24;
    const pos = opt.posCls || "s1", neg = opt.negCls || "s0";
    const m = Math.max(...items.map((d) => Math.abs(d.value))) * 1.3, mid = left + (W - left - 10) / 2;
    const x = (v) => mid + (v / m) * ((W - left - 10) / 2);
    let b = `<line class="axis" x1="${mid}" x2="${mid}" y1="0" y2="${H - 18}"/>`;
    items.forEach((d, i) => {
      const y = i * rowH + 4, a = Math.min(x(0), x(d.value)), w = Math.abs(x(d.value) - x(0));
      b += `<text x="${left - 8}" y="${y + 15}" text-anchor="end">${esc(d.label)}</text>`;
      b += `<rect class="sbar ${d.value > 0 ? pos : neg}" x="${a}" y="${y + 3}" width="${Math.max(1, w)}" height="${rowH - 10}" rx="2"/>`;
      b += `<text x="${d.value > 0 ? x(d.value) + 4 : x(d.value) - 4}" y="${y + 15}" text-anchor="${d.value > 0 ? "start" : "end"}" class="lbl">${d.value > 0 ? "+" : ""}${f3(d.value)}</text>`;
    });
    b += `<text x="${mid}" y="${H - 4}" text-anchor="middle">0</text>`;
    el.innerHTML = svg(W, H, b);
  }

  // Feature explorer
  const fSel = $("featSelect");
  const targetMean = D.eda.numeric_summary.find((s) => s.feature === "Mental_Health_Score").mean;
  fSel.innerHTML = NUM.map((f) => `<option value="${f}">${esc(NICE[f])}</option>`).join("");
  function renderFeat(f) {
    const bins = D.eda.feature_bins[f];
    const r = D.eda.numeric_summary.find((s) => s.feature === f).r_with_target;
    lineChart($("featChart"), [{ name: "mean score (band = ±1 sd)", pts: bins.map((b) => [b.x, b.y, b.y - b.sd, b.y + b.sd]) }], {
      xTitle: NICE[f] + " (group mean)", yTitle: "Mental_Health_Score", xTicks: bins.map((b) => b.x),
      xFmt: (v) => (Math.abs(v) >= 20 ? v.toFixed(0) : v.toFixed(1)), refY: targetMean, refLabel: "overall mean", yDec: 1, w: 940, h: 300,
    });
    const avgN = Math.round(bins.reduce((a, b) => a + b.n, 0) / bins.length);
    $("featNote").textContent = `Each point averages about ${avgN} students grouped by ${NICE[f]}. r = ${f2(r)}. ` +
      "The shaded band shows the spread of individual scores, not uncertainty in the mean.";
  }
  fSel.addEventListener("change", (e) => renderFeat(e.target.value));
  fSel.value = "Sleep_Hours_Per_Night";
  renderFeat(fSel.value);

  divBar($("corrChart"), D.eda.numeric_summary.filter((s) => s.feature !== "Mental_Health_Score")
    .sort((a, b) => b.r_with_target - a.r_with_target)
    .map((s) => ({ label: NICE[s.feature], value: s.r_with_target })), { left: 130, posCls: "s0", negCls: "s1" });

  hbar($("platformChart"), D.eda.platform_means.slice().reverse().map((p) => ({
    label: `${p.Most_Used_Platform} (${p.count})`, value: p.mean, cls: p.count < 60 ? "dim" : "",
  })), { left: 130, fmt: f2, axis: "mean score" });

  // Validation curve for KNN
  const kc = D.knn_curve;
  lineChart($("kChart"), ["distance", "uniform"].map((w) => ({
    name: `weights = ${w}`, pts: kc.filter((r) => r.weights === w).map((r) => [r.k, r.CV_RMSE]),
  })), { xTitle: "k (neighbours)", yTitle: "CV RMSE", yDec: 3 });

  // Learning curves
  const lcModels = [...new Set(D.learning_curves.map((r) => r.Model))];
  $("lcSelect").innerHTML = lcModels.map((m) => `<option>${esc(m)}</option>`).join("");
  function renderLC(m) {
    const rows = D.learning_curves.filter((r) => r.Model === m);
    lineChart($("lcChart"), [
      { name: "validation (CV)", pts: rows.map((r) => [r.Train_Size, r.CV_RMSE]) },
      { name: "training", pts: rows.map((r) => [r.Train_Size, r.Train_RMSE]), dash: true },
    ], { xTitle: "training rows used", yTitle: "RMSE", yMin: 0, yDec: 2 });
    const a = rows[0], z = rows[rows.length - 1], prev = rows[rows.length - 2];
    $("lcNote").textContent = `CV RMSE falls from ${f3(a.CV_RMSE)} (${a.Train_Size} rows) to ${f3(z.CV_RMSE)} (${z.Train_Size} rows); the last step still gains ${f3(prev.CV_RMSE - z.CV_RMSE)}. ` +
      (z.CV_RMSE - z.Train_RMSE > 0.2
        ? "The large train/validation gap means the model memorises its training rows, and more data would likely still help."
        : "Training and validation error are close, so the model is limited by its form more than by data size.");
  }
  $("lcSelect").addEventListener("change", (e) => renderLC(e.target.value));
  $("lcSelect").value = BEST;
  renderLC(BEST);

  // CV vs test RMSE
  groupedHbar($("cvTestChart"), D.models.map((m) => ({
    label: m.Model.replace("Baseline: ", "") + (m.Role === "selected" ? " ★" : ""), values: [m.CV_RMSE, m.Test_RMSE], sel: m.Role === "selected",
  })), ["CV RMSE (train folds)", "Test RMSE (held out)"], { w: 940, left: 260 });

  // Random vs unseen-country CV
  groupedHbar($("countryChart"), D.country.map((c) => ({
    label: c.Model.replace("Baseline: ", ""), values: [c.Random_KFold_RMSE, c.Country_GroupKFold_RMSE], sel: c.Model === BEST,
  })), ["random 5-fold", "unseen countries"], { left: 220, w: 940 });

  // Feature groups
  groupedHbar($("groupChart"), D.feature_groups.map((g) => ({
    label: g.Feature_Group.replace(/ \(.*\)/, ""), values: [g.KNN_CV_RMSE, g.Ridge_CV_RMSE], sel: g.Feature_Group === "All features",
  })), ["KNN", "Ridge"], { ref: dummy.CV_RMSE, refLabel: "mean baseline", left: 260, w: 940 });

  // Residual histogram
  const res = D.scatter.map(([a, p]) => a - p);
  const edges = [];
  for (let e = -1.5; e <= 1.5001; e += 0.25) edges.push(+e.toFixed(2));
  const last = edges.length - 2;
  const counts = edges.slice(0, -1).map((lo, i) => res.filter((r) => r >= lo && (r < edges[i + 1] || (i === last && r <= edges[i + 1]))).length);
  const outside = res.filter((r) => r < edges[0] || r > edges[edges.length - 1]).length;
  vbar($("residChart"), edges.slice(0, -1).map((e) => (e > 0 ? "+" : "") + e.toFixed(2)), counts, {
    every: 2, xTitle: "error bin start (score points)", cls: (i) => (edges[i] >= -0.25 && edges[i + 1] <= 0.25 ? "" : "dim"),
  });
  const meanRes = res.reduce((a, b) => a + b, 0) / res.length;
  $("residNote").textContent = `Mean error ${meanRes >= 0 ? "+" : ""}${f3(meanRes)}, so the model is almost unbiased overall. ` +
    `${outside} of ${res.length} errors fall outside ±1.5. Blue bars are errors within ±0.25.`;

  divBar($("biasChart"), D.subgroups.filter((g) => g.group === "band").map((g) => ({ label: g.value, value: g.bias })), { left: 130 });

  // ---------- nav ----------
  const nav = $("nav"), btn = $("menuBtn");
  btn.addEventListener("click", () => { const o = nav.classList.toggle("open"); btn.setAttribute("aria-expanded", o); });
  nav.querySelectorAll("a").forEach((a) => a.addEventListener("click", () => { nav.classList.remove("open"); btn.setAttribute("aria-expanded", false); }));
  const links = [...nav.querySelectorAll("a")];
  if ("IntersectionObserver" in window) {
    const io = new IntersectionObserver((es) => es.forEach((e) => {
      if (e.isIntersecting) links.forEach((l) => l.classList.toggle("active", l.getAttribute("href") === "#" + e.target.id));
    }), { rootMargin: "-40% 0px -55% 0px" });
    links.forEach((l) => { const s = document.querySelector(l.getAttribute("href")); if (s) io.observe(s); });
  }
})();
